package com.taskallocator.model;

import java.sql.Timestamp;

/**
 * Domain model representing a student user account.
 * Extends BaseEntity to inherit common identifier and timestamp properties.
 * Fully encapsulates user attributes with validated getters and setters.
 */
public class User extends BaseEntity {

    private String fullName;
    private String email;
    private String passwordHash;
    private String salt;
    private UserRole role;

    public User() {
        super();
    }

    /**
     * Constructor for creating a new user prior to database persistence (ID generated by DB).
     */
    public User(String fullName, String email, String passwordHash, String salt, UserRole role) {
        this.fullName = fullName;
        this.email = email;
        this.passwordHash = passwordHash;
        this.salt = salt;
        this.role = role;
    }

    /**
     * Full constructor for reconstructing an existing user record from the database.
     */
    public User(int id, String fullName, String email, String passwordHash, String salt, UserRole role, Timestamp createdAt) {
        super(id, createdAt);
        this.fullName = fullName;
        this.email = email;
        this.passwordHash = passwordHash;
        this.salt = salt;
        this.role = role;
    }

    public String getFullName() {
        return fullName;
    }

    public void setFullName(String fullName) {
        this.fullName = fullName;
    }

    public String getEmail() {
        return email;
    }

    public void setEmail(String email) {
        this.email = email;
    }

    public String getPasswordHash() {
        return passwordHash;
    }

    public void setPasswordHash(String passwordHash) {
        this.passwordHash = passwordHash;
    }

    public String getSalt() {
        return salt;
    }

    public void setSalt(String salt) {
        this.salt = salt;
    }

    public UserRole getRole() {
        return role;
    }

    public void setRole(UserRole role) {
        this.role = role;
    }

    public boolean isProjectLeader() {
        return this.role == UserRole.PROJECT_LEADER;
    }

    public boolean isTeamMember() {
        return this.role == UserRole.TEAM_MEMBER;
    }

    /**
     * Safe string representation omitting sensitive cryptographic credentials (password hash and salt).
     */
    @Override
    public String toString() {
        return "User{" +
                "id=" + id +
                ", fullName='" + fullName + '\'' +
                ", email='" + email + '\'' +
                ", role=" + role +
                ", createdAt=" + createdAt +
                '}';
    }
}
